import type { Metadata } from "next";
import "./globals.css";

const siteConfig = {
  title: "DataFlow - 데이터 관리의 가장 쉬운 방법",
  description: "복잡한 데이터 분석과 보고서 작성을 단 몇 분 만에. DataFlow로 비즈니스 성장을 가속화하세요.",
  url: "https://dataflow.example.com",
  ogImage: "https://dataflow.example.com/og-image.png",
};

export const metadata: Metadata = {
  metadataBase: new URL(siteConfig.url),
  title: {
    default: siteConfig.title,
    template: `%s | DataFlow`,
  },
  description: siteConfig.description,
  openGraph: {
    type: "website",
    locale: "ko_KR",
    url: siteConfig.url,
    title: siteConfig.title,
    description: siteConfig.description,
    siteName: "DataFlow",
    images: [
      {
        url: siteConfig.ogImage,
        width: 1200,
        height: 630,
        alt: "DataFlow Dashboard Preview",
      },
    ],
  },
  twitter: {
    card: "summary_large_image",
    title: siteConfig.title,
    description: siteConfig.description,
    images: [siteConfig.ogImage],
  },
  icons: {
    icon: "/favicon.ico",
    apple: "/apple-touch-icon.png",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="ko">
      <body className="antialiased font-sans text-gray-900 bg-white">
        {children}
      </body>
    </html>
  );
}

import { Metadata, Route } from "next";

export default function sitemap(): Metadata & { url: string; lastModified?: string | Date; changeFrequency?: "always" | "hourly" | "daily" | "weekly" | "monthly" | "yearly" | "never"; priority?: number }[] {
  return [
    {
      url: "https://dataflow.example.com",
      lastModified: new Date(),
      changeFrequency: "daily",
      priority: 1,
    },
  ];
}

import { MetadataRoute } from "next";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: {
      userAgent: "*",
      allow: "/",
      disallow: "/private/",
    },
    sitemap: "https://dataflow.example.com/sitemap.xml",
  };
}

